$ErrorActionPreference='Stop'
$all=@(Get-CimInstance Win32_Process)
$dashboard=@($all|Where-Object {$_.CommandLine -match 'dashboard' -and $_.CommandLine -match 'hermes'})
$processes=@($dashboard|ForEach-Object {@{pid=$_.ProcessId;parent=$_.ParentProcessId;name=$_.Name;created=$_.CreationDate.ToString('o');executable=$_.ExecutablePath;supervisor=($_.CommandLine -match 'dashboard_supervisor.py');profile=if($_.CommandLine -match '(?:--profile|-p)\s+([\w-]+)'){$Matches[1]}else{$null};script_paths=@([regex]::Matches($_.CommandLine,'[A-Za-z]:\\[^"\r\n]*?\.(?:py|ps1|vbs|cmd)')|ForEach-Object {$_.Value})}})
$task=Get-ScheduledTask -TaskName 'ERVP Hermes Dashboard'
$info=$task|Get-ScheduledTaskInfo
$startup=@(Get-ChildItem "$env:APPDATA\Microsoft\Windows\Start Menu\Programs\Startup" -File|Where-Object {$_.Name -match 'dashboard'}|ForEach-Object {@{path=$_.FullName;name=$_.Name;active=($_.Extension -in '.vbs','.cmd','.bat','.lnk','.exe');bytes=$_.Length;sha256=(Get-FileHash $_.FullName).Hash}})
$heldProfiles=@($all|Where-Object {$_.CommandLine -match '(?:--profile|-p)\s+(ervp-manager|ervp-orders|hermesops)(?:\s|$)' -and $_.CommandLine -match 'gateway\s+run'}|ForEach-Object {@{pid=$_.ProcessId;parent=$_.ParentProcessId;created=$_.CreationDate.ToString('o');profile=if($_.CommandLine -match '(?:--profile|-p)\s+([\w-]+)'){$Matches[1]}else{$null}}})
[pscustomobject]@{at=(Get-Date -Format o);dashboard_processes=$processes;dashboard_children=@($all|Where-Object {$_.ParentProcessId -in @($dashboard|ForEach-Object {$_.ProcessId})}|ForEach-Object {@{pid=$_.ProcessId;parent=$_.ParentProcessId;name=$_.Name;created=$_.CreationDate.ToString('o')}});task=@{name=$task.TaskName;enabled=$task.Settings.Enabled;state=[string]$task.State;last_run=$info.LastRunTime.ToString('o');last_result=$info.LastTaskResult;script_paths=@($task.Actions|ForEach-Object {[regex]::Matches($_.Arguments,'[A-Za-z]:\\[^"\r\n]*?\.(?:ps1|vbs|cmd|py)')|ForEach-Object {$_.Value}})};startup=$startup;held_gateway_processes=$heldProfiles}|ConvertTo-Json -Depth 10
